import { useState, useEffect, useRef } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Helmet } from 'react-helmet-async';
import { Send, Bot, User, Trash2, ChevronDown } from 'lucide-react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../lib/axios';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

export default function ChatPage() {
    const { id } = useParams();
    const navigate = useNavigate();
    const queryClient = useQueryClient();
    const [input, setInput] = useState('');
    const scrollRef = useRef(null);

    // Model Selection State
    const [selectedModel, setSelectedModel] = useState("llama-3.3-70b-versatile");
    const [showModelMenu, setShowModelMenu] = useState(false);

    const models = [
        { id: "llama-3.3-70b-versatile", name: "Llama 3.3 70B (Smartest)" },
        { id: "deepseek-r1-distill-llama-70b", name: "DeepSeek R1 70B (Reasoning)" },
        { id: "llama3-70b-8192", name: "Llama 3 70B (Fast)" },
        { id: "gemma-2-9b-it", name: "Gemma 2 9B (Lightweight)" }
    ];

    const { data: messages = [], isLoading: isHistoryLoading } = useQuery({
        queryKey: ['chat', id],
        queryFn: async () => {
            if (!id) return [];
            const res = await api.get(`/chat/${id}`);
            return res.data;
        },
        enabled: !!id,
    });

    const sendMutation = useMutation({
        mutationFn: async ({ content, conversationId, model }) => {
            return api.post('/chat/send', { message: content, conversationId, model });
        },
        onMutate: async ({ content, conversationId }) => {
            await queryClient.cancelQueries({ queryKey: ['chat', conversationId] });
            const previousMessages = queryClient.getQueryData(['chat', conversationId]) || [];

            // Optimistic update
            const newMsg = { role: 'user', content, timestamp: new Date() };
            queryClient.setQueryData(['chat', conversationId], [...previousMessages, newMsg]);

            return { previousMessages };
        },
        onSuccess: (res, vars) => {
            const aiContent = res.data.response;
            queryClient.setQueryData(['chat', vars.conversationId], old => [
                ...old,
                { role: 'assistant', content: aiContent, timestamp: new Date() }
            ]);
            // Invalidate conversations list in sidebar
            queryClient.invalidateQueries({ queryKey: ['conversations'] });
        },
        onError: (err, vars, context) => {
            queryClient.setQueryData(['chat', vars.conversationId], context.previousMessages);
        }
    });

    // Auto-scroll logic
    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages]);

    const handleClear = async () => {
        if (!id) return;
        if (!window.confirm("Clear all chat history?")) return;
        try {
            await api.delete(`/chat/conversations/${id}`);
            queryClient.invalidateQueries({ queryKey: ['conversations'] });
            navigate('/chat');
        } catch (err) {
            console.error(err);
        }
    };

    const handleSend = async (e, overrideText) => {
        if (e) e.preventDefault();
        const msgContent = overrideText ?? input;
        if (!msgContent.trim()) return;

        let targetId = id;

        // If no ID (on /chat), create new convo first
        if (!targetId) {
            try {
                const res = await api.post('/chat/conversations');
                targetId = res.data._id;
                // Pre-seed the cache for the new conversation so optimistic update works immediately
                queryClient.setQueryData(['chat', targetId], []);
                navigate(`/chat/${targetId}`);
            } catch (err) {
                console.error(err);
                return;
            }
        }

        setInput(''); // Clear input immediately

        sendMutation.mutate({
            content: msgContent,
            conversationId: targetId,
            model: selectedModel
        });
    };

    const suggestions = [
        { icon: "💪", text: "Help me set a new gym habit" },
        { icon: "🤔", text: "How are my habits going?" },
        { icon: "📊", text: "Show me my progress" },
        { icon: "✨", text: "Give me motivation" },
    ];

    const handleSuggestionClick = (text) => {
        setInput(text);
        // Auto-submit the suggestion immediately
        handleSend({ preventDefault: () => { } }, text);
    };

    return (
        <div className="fixed inset-x-0 bottom-0 top-[65px] md:static md:top-auto md:bottom-auto md:inset-x-auto md:h-[calc(100vh-6rem)] flex flex-col bg-zinc-900/50 md:rounded-2xl border-t md:border border-zinc-800 overflow-hidden relative md:m-6 shadow-2xl z-0">
            <Helmet>
                <title>Chat | Life OS</title>
            </Helmet>
            {/* Model Selector - Centered Top */}
            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-10 w-full max-w-xs flex justify-center">
                <div className="relative">
                    <button
                        onClick={() => setShowModelMenu(!showModelMenu)}
                        className="flex items-center gap-2 px-3 py-1.5 bg-zinc-800/80 hover:bg-zinc-700 rounded-lg text-xs md:text-sm text-zinc-300 hover:text-white transition-all border border-zinc-700/50 backdrop-blur-sm shadow-lg"
                    >
                        <span className="truncate max-w-[150px]">{models.find(m => m.id === selectedModel)?.name}</span>
                        <ChevronDown className="w-3.5 h-3.5" />
                    </button>



                    {showModelMenu && (
                        <div className="absolute left-1/2 -translate-x-1/2 top-full mt-2 w-64 bg-zinc-800 border border-zinc-700 rounded-xl shadow-xl overflow-hidden py-1 animate-in fade-in slide-in-from-top-2 z-50">
                            {models.map(model => (
                                <button
                                    key={model.id}
                                    onClick={() => {
                                        setSelectedModel(model.id);
                                        setShowModelMenu(false);
                                    }}
                                    className={`w-full text-left px-4 py-2.5 text-sm transition-colors flex items-center justify-between ${selectedModel === model.id
                                        ? 'bg-indigo-600/10 text-indigo-400'
                                        : 'text-zinc-300 hover:bg-zinc-700/50 hover:text-white'
                                        }`}
                                >
                                    {model.name}
                                    {selectedModel === model.id && <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </div>

            {
                !id && messages.length === 0 ? (
                    <div className="flex-1 flex flex-col items-center justify-center p-8 text-center">
                        <div className="w-20 h-20 bg-gradient-to-tr from-indigo-600 to-purple-600 rounded-2xl flex items-center justify-center mb-6 shadow-lg shadow-indigo-500/20">
                            <Bot className="w-10 h-10 text-white" />
                        </div>
                        <h2 className="text-2xl font-bold text-white mb-2">How can I help you today?</h2>
                        <p className="text-zinc-400 max-w-md mb-8">
                            I can help you track your habits, analyze your progress, and answer your questions.
                        </p>

                        {/* Suggestions */}
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full max-w-lg mb-8">
                            {suggestions.map((s, i) => (
                                <button
                                    key={i}
                                    onClick={() => handleSuggestionClick(s.text)}
                                    className="p-4 bg-zinc-800/50 hover:bg-zinc-800 border border-zinc-700/50 hover:border-indigo-500/50 rounded-xl text-left transition-all group"
                                >
                                    <div className="text-lg mb-1">{s.icon}</div>
                                    <div className="text-sm text-zinc-300 group-hover:text-white font-medium">{s.text}</div>
                                </button>
                            ))}
                        </div>

                        <form onSubmit={handleSend} className="w-full max-w-lg relative">
                            <textarea
                                autoFocus
                                rows={1}
                                value={input}
                                onChange={(e) => setInput(e.target.value)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter' && !e.shiftKey) {
                                        e.preventDefault();
                                        handleSend(e);
                                    }
                                }}
                                placeholder="Message Life OS..."
                                className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 pr-24 text-white placeholder-zinc-500 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all shadow-inner resize-none min-h-[56px] custom-scrollbar"
                                style={{ maxHeight: '200px' }}
                            />
                            <button
                                type="submit"
                                disabled={sendMutation.isPending || !input.trim()}
                                className="absolute right-2 top-2 p-2 bg-indigo-600 hover:bg-indigo-500 rounded-lg text-white transition-colors disabled:opacity-50"
                            >
                                <Send className="w-5 h-5" />
                            </button>
                        </form>
                    </div>
                ) : (
                    <>
                        <div className="flex-1 overflow-y-auto p-4 md:p-6 pt-14 md:pt-6 space-y-6 scroll-smooth overscroll-contain" ref={scrollRef}>
                            <div className="max-w-5xl mx-auto space-y-6">
                                {messages.map((msg, idx) => (
                                    <div key={idx} className={`w-full flex gap-2 md:gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''} group`}>
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${msg.role === 'user' ? 'bg-indigo-600' : 'bg-zinc-700'}`}>
                                            {msg.role === 'user' ? <User className="w-5 h-5 text-white" /> : <Bot className="w-5 h-5 text-indigo-400" />}
                                        </div>
                                        <div className={`max-w-[85%] md:max-w-[80%] rounded-2xl px-5 py-3 shadow-sm ${msg.role === 'user'
                                            ? 'bg-indigo-600 text-white rounded-tr-sm'
                                            : 'bg-zinc-800 text-zinc-100 rounded-tl-sm'
                                            }`}>
                                            <div className="markdown-body text-sm md:text-base leading-relaxed prose prose-invert prose-sm max-w-none">
                                                <ReactMarkdown
                                                    remarkPlugins={[remarkGfm]}
                                                    components={{
                                                        p: ({ node, ...props }) => <p className="mb-2 last:mb-0" {...props} />,
                                                        ul: ({ node, ...props }) => <ul className="list-disc ml-4 mb-2" {...props} />,
                                                        ol: ({ node, ...props }) => <ol className="list-decimal ml-4 mb-2" {...props} />,
                                                        li: ({ node, ...props }) => <li className="mb-1" {...props} />,
                                                        code: ({ node, className, children, ...props }) => (
                                                            <code className={`${className ?? ''} bg-zinc-700/50 px-1 py-0.5 rounded text-xs font-mono`} {...props}>
                                                                {children}
                                                            </code>
                                                        ),
                                                        pre: ({ node, children, ...props }) => (
                                                            <pre className="bg-zinc-900/50 p-3 rounded-lg overflow-x-auto my-2 text-xs font-mono border border-zinc-700/50" {...props}>
                                                                {children}
                                                            </pre>
                                                        )
                                                    }}
                                                >
                                                    {msg.content}
                                                </ReactMarkdown>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                                {sendMutation.isPending && (
                                    <div className="flex gap-4">
                                        <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-indigo-600 to-purple-600 flex items-center justify-center shrink-0">
                                            <Bot className="w-5 h-5" />
                                        </div>
                                        <div className="bg-zinc-900 rounded-2xl px-5 py-3 rounded-tl-sm flex gap-1 items-center border border-zinc-800">
                                            <span className="w-2 h-2 bg-zinc-500 rounded-full animate-bounce"></span>
                                            <span className="w-2 h-2 bg-zinc-500 rounded-full animate-bounce delay-100"></span>
                                            <span className="w-2 h-2 bg-zinc-500 rounded-full animate-bounce delay-200"></span>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>

                        <form onSubmit={handleSend} className="p-4 bg-zinc-900/80 backdrop-blur-md border-t border-zinc-800">
                            <div className="relative max-w-5xl mx-auto">
                                <textarea
                                    autoFocus
                                    rows={1}
                                    value={input}
                                    onChange={(e) => setInput(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter' && !e.shiftKey) {
                                            e.preventDefault();
                                            handleSend(e);
                                        }
                                    }}
                                    placeholder="Message Life OS..."
                                    className="w-full bg-zinc-800 border border-zinc-700 rounded-xl px-4 py-3 pr-24 text-white placeholder-zinc-500 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all font-medium resize-none min-h-[56px] custom-scrollbar"
                                    style={{ maxHeight: '200px' }}
                                />
                                <button
                                    type="submit"
                                    disabled={sendMutation.isPending || !input.trim()}
                                    className="absolute right-2 top-2 p-2 bg-indigo-600 hover:bg-indigo-500 rounded-lg text-white transition-colors disabled:opacity-50 shadow-lg shadow-indigo-500/20"
                                >
                                    <Send className="w-5 h-5" />
                                </button>
                            </div>
                        </form>
                    </>
                )
            }
        </div >
    );
}

import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Sparkles, Activity, Zap, MessageSquare, CheckCircle2, ArrowRight, Book, Target, TrendingUp, Award, Brain, Calendar, Flag } from 'lucide-react';
import { Helmet } from 'react-helmet-async';
import { Link } from 'react-router-dom';
import api from '../lib/axios';

const QUOTES = [
    "The only way to do great work is to love what you do.",
    "Your time is limited, so don't waste it living someone else's life.",
    "Believe you can and you're halfway there.",
    "Success is not final, failure is not fatal: it is the courage to continue that counts.",
    "The future belongs to those who believe in the beauty of their dreams.",
    "Do something today that your future self will thank you for.",
    "Productivity is being able to do things that you were never able to do before.",
    "Focus on being productive instead of busy."
];

export default function Dashboard() {
    const { user } = useAuth();
    const [time, setTime] = useState(new Date().getHours());
    const [habits, setHabits] = useState([]);
    const [chats, setChats] = useState([]);
    const [journals, setJournals] = useState([]);
    const [goals, setGoals] = useState([]);
    const [quote, setQuote] = useState("");
    const [loading, setLoading] = useState(true);
    const [stats, setStats] = useState(null);

    useEffect(() => {
        // Set Greeting Phrase
        // Set Quote based on day of year to be consistent for 24h
        const dayOfYear = Math.floor((new Date() - new Date(new Date().getFullYear(), 0, 0)) / 1000 / 60 / 60 / 24);
        setQuote(QUOTES[dayOfYear % QUOTES.length]);

        const fetchData = async () => {
            try {
                const [habitsRes, chatsRes, journalsRes, statsRes, goalsRes] = await Promise.all([
                    api.get('/habits'),
                    api.get('/chat/conversations'),
                    api.get('/journal'),
                    api.get('/search/stats'),
                    api.get('/goals'),
                ]);
                setHabits(Array.isArray(habitsRes.data) ? habitsRes.data : []);
                setChats(Array.isArray(chatsRes.data) ? chatsRes.data.slice(0, 3) : []);
                setJournals(Array.isArray(journalsRes.data) ? journalsRes.data : []);
                setStats(statsRes.data || null);
                setGoals(Array.isArray(goalsRes.data) ? goalsRes.data.filter(g => g.status === 'active').slice(0, 4) : []);
            } catch (err) {
                console.error("Dashboard Fetch Error", err);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, []);

    // Helper for Local Date String (YYYY-MM-DD)
    const getLocalDateString = (date) => {
        const d = new Date(date);
        const offset = d.getTimezoneOffset() * 60000;
        return new Date(d.getTime() - offset).toISOString().split('T')[0];
    };

    const greeting = time < 12 ? 'Good morning' : time < 18 ? 'Good afternoon' : 'Good evening';

    // Calculate Habit Progress
    const todayStr = getLocalDateString(new Date());
    const completedToday = habits.filter(h =>
        h.completedDates.some(d => getLocalDateString(d) === todayStr)
    ).length;
    const progress = habits.length > 0 ? (completedToday / habits.length) * 100 : 0;

    // Calculate Last 7 Days Data for Chart
    // Calculate Last 7 Days Data for Chart
    const chartData = Array.from({ length: 7 }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (6 - i)); // Order: -6, -5, ... 0 (Today)
        return d;
    }).map(date => {
        const dateStr = getLocalDateString(date);
        const dayLabel = date.toLocaleDateString('en-US', { weekday: 'short' });

        if (habits.length === 0) return { day: dayLabel, fullDate: dateStr, value: 0 };

        // Check completion for this specific date (Local Time)
        const completedCount = habits.filter(h =>
            h.completedDates.some(cd => getLocalDateString(cd) === dateStr)
        ).length;

        return {
            day: dayLabel,
            fullDate: dateStr,
            value: Math.round((completedCount / habits.length) * 100)
        };
    });

    const isChartEmpty = chartData.every(d => d.value === 0);

    return (
        <div className="p-4 md:p-8 space-y-6 md:space-y-8 max-w-7xl mx-auto">
            <Helmet>
                <title>Dashboard | Life OS</title>
            </Helmet>

            {/* Header Section */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <h1 className="text-3xl md:text-5xl font-bold text-white tracking-tight mb-2">
                        {greeting}, <span className="text-indigo-400">{user?.name ? user.name.split(' ')[0] : 'User'}</span>
                    </h1>
                    <p className="text-zinc-400 text-sm md:text-lg max-w-2xl">
                        "{quote}"
                    </p>
                </div>
                <div className="text-right hidden md:block">
                    <div className="text-zinc-500 text-sm font-mono">{new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</div>
                </div>
            </div>

            {/* Main Details Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6">

                {/* 1. Quick Chat / AI Card */}
                <Link to="/chat" className="group relative glass-card p-6 overflow-hidden flex flex-col">
                    <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:opacity-20 transition-opacity">
                        <Sparkles className="w-24 h-24 text-indigo-500" />
                    </div>

                    <div className="relative z-10 flex flex-col h-full">
                        <div className="bg-indigo-500/20 w-fit p-3 rounded-2xl mb-4 group-hover:scale-110 transition-transform duration-300">
                            <Sparkles className="w-6 h-6 text-indigo-400" />
                        </div>
                        <h3 className="text-xl font-semibold text-white mb-2">Ask AI</h3>
                        <p className="text-zinc-400 text-sm mb-4 flex-1">Draft emails, brainstorm ideas, or plan your schedule.</p>

                        {/* Recent Chats Mini-List */}
                        <div className="space-y-2 mb-4">
                            {chats.slice(0, 2).map(chat => (
                                <div key={chat._id} className="text-xs text-zinc-500 truncate flex items-center gap-2">
                                    <MessageSquare className="w-3 h-3" />
                                    {chat.title || "New Conversation"}
                                </div>
                            ))}
                        </div>

                        <div className="mt-auto flex items-center gap-2 text-indigo-400 text-sm font-medium">
                            Start New Chat <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                        </div>
                    </div>
                </Link>

                {/* 2. Focus Mode Card */}
                <Link to="/focus" className="group relative glass-card p-6 overflow-hidden flex flex-col">
                    <div className="absolute -bottom-8 -right-8 p-8 opacity-10 group-hover:opacity-20 transition-opacity">
                        <Zap className="w-40 h-40 text-purple-500" />
                    </div>

                    <div className="relative z-10 flex flex-col h-full">
                        <div className="bg-purple-500/20 w-fit p-3 rounded-2xl mb-4 group-hover:scale-110 transition-transform duration-300">
                            <Zap className="w-6 h-6 text-purple-400" />
                        </div>
                        <h3 className="text-xl font-semibold text-white mb-2">Focus Mode</h3>
                        <p className="text-zinc-400 text-sm mb-6 flex-1">Block distractions and enter the flow state.</p>

                        <div className="mt-auto">
                            <div className="flex items-center gap-2 text-purple-400 text-sm font-medium bg-purple-500/10 py-2 px-3 rounded-lg w-fit group-hover:bg-purple-500/20 transition-colors">
                                Start Session <ArrowRight className="w-4 h-4" />
                            </div>
                        </div>
                    </div>
                </Link>

                {/* 3. Habits Status Card */}
                <Link to="/habits" className="group relative glass-card p-6 overflow-hidden flex flex-col">
                    <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:opacity-20 transition-opacity">
                        <Activity className="w-24 h-24 text-green-500" />
                    </div>

                    <div className="relative z-10 flex flex-col h-full">
                        <div className="bg-green-500/20 w-fit p-3 rounded-2xl mb-4 group-hover:scale-110 transition-transform duration-300">
                            <Activity className="w-6 h-6 text-green-400" />
                        </div>
                        <h3 className="text-xl font-semibold text-white mb-2">Daily Goals</h3>

                        <div className="flex items-end gap-2 mb-2">
                            <span className="text-3xl font-bold text-white">{completedToday}</span>
                            <span className="text-zinc-500 mb-1 text-xs">/ {habits.length} done</span>
                        </div>

                        {/* Mini Progress Bar */}
                        <div className="w-full bg-zinc-800 h-1.5 rounded-full overflow-hidden mb-4">
                            <div
                                className="bg-green-500 h-full transition-all duration-1000 ease-out"
                                style={{ width: `${progress}%` }}
                            ></div>
                        </div>

                        <div className="mt-auto space-y-1.5">
                            {habits.slice(0, 2).map(h => {
                                const isDone = h.completedDates.some(d => new Date(d).toISOString().split('T')[0] === todayStr);
                                return (
                                    <div key={h._id} className="flex items-center gap-2 text-xs">
                                        <div className={`w-3 h-3 rounded-full flex items-center justify-center border ${isDone ? 'bg-green-500 border-green-500' : 'border-zinc-700'}`}>
                                            {isDone && <CheckCircle2 className="w-2.5 h-2.5 text-black" />}
                                        </div>
                                        <span className={`truncate ${isDone ? 'text-zinc-500 line-through' : 'text-zinc-300'}`}>{h.name}</span>
                                    </div>
                                );
                            })}
                            {habits.length > 2 && <div className="text-[10px] text-zinc-500 pl-5">+{habits.length - 2} more...</div>}
                        </div>
                    </div>
                </Link>

                {/* 4. Journal Card */}
                <Link to="/journal" className="group relative glass-card p-6 overflow-hidden flex flex-col">
                    <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:opacity-20 transition-opacity">
                        <Book className="w-24 h-24 text-pink-500" />
                    </div>

                    <div className="relative z-10 flex flex-col h-full">
                        <div className="bg-pink-500/20 w-fit p-3 rounded-2xl mb-4 group-hover:scale-110 transition-transform duration-300">
                            <Book className="w-6 h-6 text-pink-400" />
                        </div>
                        <h3 className="text-xl font-semibold text-white mb-2">Journal</h3>

                        {journals.length > 0 && new Date(journals[0].date).toDateString() === new Date().toDateString() ? (
                            <>
                                <p className="text-zinc-400 text-sm mb-2">Today's entry captured.</p>
                                <div className="mt-auto">
                                    <div className="bg-zinc-800/50 p-3 rounded-lg border border-zinc-700/50">
                                        <div className="text-xs text-zinc-500 mb-1">Mood</div>
                                        <div className="text-white font-medium capitalize">{journals[0].mood || 'Neutral'}</div>
                                    </div>
                                </div>
                            </>
                        ) : (
                            <>
                                <p className="text-zinc-400 text-sm mb-6 flex-1">Reflect on your day and clear your mind.</p>
                                <div className="mt-auto">
