function EditTimerModal({ onSave, onCancel, initialSeconds }) {
    // Convert total seconds to H/M/S
    const h = Math.floor(initialSeconds / 3600);
    const m = Math.floor((initialSeconds % 3600) / 60);
    const s = initialSeconds % 60;

    const [hours, setHours] = useState(h);
    const [minutes, setMinutes] = useState(m);
    const [seconds, setSeconds] = useState(s);
    const [name, setName] = useState("Focus Session");

    const handleSave = () => {
        const total = (hours * 3600) + (minutes * 60) + seconds;
        onSave(total, name);
    };

    // Helper for number inputs
    const NumberInput = ({ value, setter, max }) => (
        <div className="flex flex-col items-center">
            <button onClick={() => setter(v => (v + 1) % (max + 1))} className="text-zinc-500 hover:text-indigo-400 p-1">
                <ChevronUp className="w-5 h-5" />
            </button>
            <div className="text-3xl font-bold font-mono text-white w-16 text-center bg-transparent border-none appearance-none m-0">
                {value.toString().padStart(2, '0')}
            </div>
            <button onClick={() => setter(v => (v - 1 + (max + 1)) % (max + 1))} className="text-zinc-500 hover:text-indigo-400 p-1">
                <ChevronDown className="w-5 h-5" />
            </button>
        </div>
    );

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-zinc-900 border border-zinc-700/50 rounded-2xl p-6 w-full max-w-sm shadow-2xl relative" onClick={e => e.stopPropagation()}>
                {/* Header */}
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-lg font-bold text-white">Edit timer</h2>
                    <div className="flex gap-2">
                        <button className="text-zinc-500 hover:text-red-400 transition-colors">
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                </div>

                {/* Time Pickers */}
                <div className="flex items-center justify-center gap-2 mb-8 relative">
                    <NumberInput value={hours} setter={setHours} max={23} />
                    <span className="text-2xl font-bold text-zinc-600 pb-2">:</span>
                    <NumberInput value={minutes} setter={setMinutes} max={59} />
                    <span className="text-2xl font-bold text-zinc-600 pb-2">:</span>
                    <NumberInput value={seconds} setter={setSeconds} max={59} />

                    {/* Blue underline effect from screenshot */}
                    <div className="absolute bottom-0 left-0 right-0 h-px bg-zinc-700 mt-2"></div>
                    <div className="absolute bottom-0 left-12 right-12 h-0.5 bg-indigo-500"></div>
                </div>

                {/* Name Input */}
                <div className="mb-6">
                    <div className="relative">
                        <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
                            <Edit className="h-4 w-4 text-zinc-500" />
                        </div>
                        <input
                            type="text"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            className="bg-zinc-800 border border-zinc-700 text-zinc-300 text-sm rounded-lg focus:ring-indigo-500 focus:border-indigo-500 block w-full pl-10 p-2.5 placeholder-zinc-500"
                            placeholder="Timer Name"
                        />
                    </div>
                </div>

                {/* Actions */}
                <div className="flex gap-3 grid grid-cols-2">
                    <button
                        onClick={handleSave}
                        className="flex items-center justify-center gap-2 text-white bg-indigo-600 hover:bg-indigo-500 font-medium rounded-lg text-sm px-5 py-2.5 transition-colors"
                    >
                        <Save className="w-4 h-4" />
                        Save
                    </button>
                    <button
                        onClick={onCancel}
                        className="flex items-center justify-center gap-2 text-zinc-300 bg-transparent border border-zinc-600 hover:bg-zinc-800 font-medium rounded-lg text-sm px-5 py-2.5 transition-colors"
                    >
                        <X className="w-4 h-4" />
                        Cancel
                    </button>
                </div>
            </div>
        </div>
    );
}

export default function FocusPage() {
    const [initialTime, setInitialTime] = useState(DEFAULT_TIME);
    const [timeLeft, setTimeLeft] = useState(DEFAULT_TIME);
    const [isActive, setIsActive] = useState(false);
    const [selectedHabitId, setSelectedHabitId] = useState('');
    const [showEditModal, setShowEditModal] = useState(false);

    // Notification permission state
    const [notifPermission, setNotifPermission] = useState(
        typeof Notification !== 'undefined' ? Notification.permission : 'denied'
    );

    // Request notification permission
    const requestNotifPermission = async () => {
        if (typeof Notification === 'undefined') return;
        const result = await Notification.requestPermission();
        setNotifPermission(result);
    };

    // Audio State
    const [selectedSound, setSelectedSound] = useState('meditation5');
    const [isMuted, setIsMuted] = useState(false);
    const [volume, setVolume] = useState(0.5);
    const [isPlayingSound, setIsPlayingSound] = useState(false);
    const [isAudioLoading, setIsAudioLoading] = useState(false);
    const audioRef = useRef(null);

    // Fetch habits for selection
    const { data: habits = [] } = useQuery({
        queryKey: ['habits'],
        queryFn: async () => {
            const res = await api.get('/habits');
            return res.data;
        }
    });

    // Timer logic
    useEffect(() => {
        let interval = null;
        if (isActive && timeLeft > 0) {
            interval = setInterval(() => {
                setTimeLeft((time) => time - 1);
            }, 1000);
        } else if (timeLeft === 0) {
            setIsActive(false);
            if (Notification.permission === 'granted') {
                new Notification("Focus Session Complete!");
            }
        }
        return () => clearInterval(interval);
    }, [isActive, timeLeft]);

    // Update audio volume when slider changes
    useEffect(() => {
        if (audioRef.current) {
            audioRef.current.volume = volume;
            audioRef.current.muted = isMuted;
        }
    }, [volume, isMuted]);

    const toggleTimer = () => {
        setIsActive(!isActive);
    };

    const toggleMusic = async () => {
        if (selectedSound === 'none') {
            alert('Please select a music option first');
            return;
        }

        if (isAudioLoading || !audioRef.current) {
            return; // Prevent rapid clicks
        }

        try {
            setIsAudioLoading(true);

            if (isPlayingSound) {
                // Pause music
                audioRef.current.pause();
                setIsPlayingSound(false);
            } else {
                // Play music
                await audioRef.current.play();
                setIsPlayingSound(true);
            }
        } catch (err) {
            console.error('Audio control error:', err);
            setIsPlayingSound(false);
        } finally {
            setIsAudioLoading(false);
        }
    };

    const resetTimer = () => {
        setIsActive(false);
        setIsPlayingSound(false);
        setTimeLeft(initialTime);
    };

    const handleSaveTime = (newSeconds, newName) => {
        setInitialTime(newSeconds);
        setTimeLeft(newSeconds);
        setShowEditModal(false);
    };

    const formatTime = (seconds) => {
        const h = Math.floor(seconds / 3600);
        const m = Math.floor((seconds % 3600) / 60);
        const s = seconds % 60;

        if (h > 0) {
            // Show hours if present: H:MM:SS
            return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
        }
        // Otherwise just MM:SS
        return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
    };

    // Calculate progress for circle
    const progress = initialTime > 0 ? ((initialTime - timeLeft) / initialTime) * 100 : 0;
    const strokeDasharray = 2 * Math.PI * 120;
    const strokeDashoffset = strokeDasharray - (progress / 100) * strokeDasharray;

    const currentSoundUrl = FOCUS_SOUNDS.find(s => s.id === selectedSound)?.url;

    return (
        <div className="min-h-[80vh] flex flex-col items-center justify-center p-4 relative overflow-hidden">
            <Helmet>
                <title>Focus Mode | Life OS</title>
            </Helmet>

            {/* Audio Player */}
            {currentSoundUrl && (
                <audio
                    key={selectedSound}
                    ref={audioRef}
                    src={currentSoundUrl}
                    loop
                    preload="auto"
                    onLoadedData={() => {
                        console.log('Audio loaded:', selectedSound);
                        // Reset loading state
                        setIsAudioLoading(false);
                        if (audioRef.current) {
                            audioRef.current.volume = volume;
                            audioRef.current.muted = isMuted;
                            // Auto-play if was previous playing or just switched
                            if (isPlayingSound) {
                                audioRef.current.play().catch(e => console.error("Auto-play blocked:", e));
                            }
                        }
                    }}
                    onPlay={() => {
                        console.log('Audio playing:', selectedSound);
                        setIsPlayingSound(true);
                    }}
                    onPause={() => {
                        console.log('Audio paused:', selectedSound);
                        setIsPlayingSound(false);
                    }}
                    onError={(e) => {
                        console.error('Audio load error:', selectedSound, e);
                        setIsPlayingSound(false);
                        setIsAudioLoading(false);
                        alert("Could not load this audio track. Please try another one.");
                    }}
                />
            )}

            {/* Modal */}
            {showEditModal && (
                <EditTimerModal
                    initialSeconds={initialTime}
                    onSave={handleSaveTime}
                    onCancel={() => setShowEditModal(false)}
                />
            )}

            {/* Background Ambience */}
            <div className={`absolute inset-0 transition-opacity duration-1000 ${isActive ? 'opacity-20' : 'opacity-5'}`}>
                <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-600 rounded-full mix-blend-multiply filter blur-3xl animate-blob"></div>
                <div className="absolute top-1/3 right-1/4 w-96 h-96 bg-purple-600 rounded-full mix-blend-multiply filter blur-3xl animate-blob animation-delay-2000"></div>
            </div>

            <div className="z-10 flex flex-col items-center w-full max-w-md space-y-8">

                {/* Header */}
                <div className="text-center space-y-2">
                    <h1 className="text-4xl font-bold text-white tracking-tight">Focus Mode</h1>
                    <p className="text-zinc-400">Select a habit and start your session</p>
                </div>

                {/* Notification Permission Banner */}
                {notifPermission === 'default' && (
                    <div className="w-full flex items-center justify-between gap-3 bg-indigo-500/10 border border-indigo-500/30 rounded-xl px-4 py-3">
                        <div className="flex items-center gap-2 text-sm text-indigo-300">
                            <span className="text-lg">🔔</span>
                            <span>Enable notifications to get alerted when your focus session ends.</span>
                        </div>
                        <button
                            onClick={requestNotifPermission}
                            className="shrink-0 px-3 py-1.5 text-xs font-semibold bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-colors"
                        >
                            Enable
                        </button>
                    </div>
                )}
                {notifPermission === 'denied' && (
                    <div className="w-full flex items-center gap-3 bg-zinc-800/60 border border-zinc-700/50 rounded-xl px-4 py-2.5">
                        <span className="text-lg">🔕</span>
                        <span className="text-xs text-zinc-500">Notifications are blocked. Enable them in your browser settings to get session-end alerts.</span>
                    </div>
                )}

                {/* Habit Selector */}
                <div className="w-full">
                    <select
                        value={selectedHabitId}
                        onChange={(e) => setSelectedHabitId(e.target.value)}
                        className="w-full bg-zinc-900/50 border border-zinc-700 text-white rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all appearance-none cursor-pointer"
                        disabled={isActive}
                    >
                        <option value="" disabled>Select a task to focus on...</option>
                        {habits.map(h => (
                            <option key={h._id} value={h._id}>{h.name}</option>
                        ))}
                    </select>
                </div>

                {/* Sound Selector Compact */}
                <div className="w-full flex items-center gap-3 bg-zinc-900/30 border border-zinc-800 rounded-xl p-3">
                    <div className="p-2 bg-indigo-500/10 rounded-lg text-indigo-400">
                        <Music className="w-5 h-5" />
                    </div>
                    <div className="flex-1">
                        <select
                            value={selectedSound}
                            onChange={(e) => {
                                setIsPlayingSound(false); // Stop music when changing sound
                                setSelectedSound(e.target.value);
                            }}
                            className="w-full bg-transparent text-sm text-zinc-300 focus:outline-none border-none cursor-pointer"
                        >
                            {FOCUS_SOUNDS.map(s => (
                                <option key={s.id} value={s.id} className="bg-zinc-900">{s.name}</option>
                            ))}
                        </select>
                    </div>
                    <div className="flex items-center gap-2 border-l border-white/5 pl-3">
                        <button
                            onClick={() => setIsMuted(!isMuted)}
                            className="text-zinc-400 hover:text-white transition-colors"
                        >
                            {isMuted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                        </button>
                        <input
                            type="range"
                            min="0"
                            max="1"
                            step="0.1"
                            value={isMuted ? 0 : volume}
                            onChange={(e) => {
                                setVolume(parseFloat(e.target.value));
                                setIsMuted(false);
                            }}
                            className="w-20 accent-indigo-500 h-1.5 bg-zinc-700 rounded-lg appearance-none cursor-pointer"
                        />
                    </div>
                </div>

                {/* Timer Display */}
                <div className="relative group cursor-pointer" onClick={() => !isActive && setShowEditModal(true)}>
                    {/* Ring */}
                    <div className="relative w-72 h-72 flex items-center justify-center">
                        <svg className="w-full h-full transform -rotate-90">
                            <circle cx="50%" cy="50%" r="120" fill="none" stroke="#27272a" strokeWidth="8" />
                            <circle
                                cx="50%" cy="50%" r="120" fill="none"
                                stroke={isActive ? "#6366f1" : "#71717a"}
                                strokeWidth="8" strokeLinecap="round"
                                style={{ strokeDasharray, strokeDashoffset, transition: 'stroke-dashoffset 1s linear' }}
                            />
                        </svg>

                        {/* Text */}
                        <div className="absolute flex flex-col items-center">
                            <span className="text-6xl font-mono font-bold text-white tracking-wider tabular-nums">
                                {formatTime(timeLeft)}
                            </span>
                            {isActive ? (
                                <span className="text-indigo-400 text-sm mt-2 animate-pulse uppercase tracking-widest font-semibold">
                                    Focusing
                                </span>
                            ) : (
                                <div className="flex items-center gap-1 text-zinc-500 text-sm mt-2 group-hover:text-indigo-400 transition-colors">
                                    <Edit className="w-3 h-3" />
                                    <span className="uppercase tracking-widest font-semibold">Edit Timer</span>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Controls */}
                <div className="flex items-center gap-4">
                    {/* Timer Control */}
                    <button
                        onClick={toggleTimer}
                        className={`p-6 rounded-full transition-all transform hover:scale-105 shadow-xl ${isActive
                            ? 'bg-zinc-800 text-red-400 hover:bg-zinc-700'
                            : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-indigo-500/30'
                            }`}
                        title={isActive ? 'Pause Timer' : 'Start Timer'}
                    >
                        {isActive ? <Pause className="w-8 h-8 fill-current" /> : <Play className="w-8 h-8 fill-current ml-1" />}
                    </button>

                    {/* Music Control */}
                    <button
                        onClick={toggleMusic}
                        disabled={selectedSound === 'none' || isAudioLoading}
                        className={`p-5 rounded-full transition-all transform hover:scale-105 shadow-lg ${selectedSound === 'none' || isAudioLoading
                            ? 'bg-zinc-900 text-zinc-600 cursor-not-allowed'
                            : isPlayingSound
                                ? 'bg-purple-600 text-white hover:bg-purple-500 shadow-purple-500/30'
                                : 'bg-zinc-800 text-purple-400 hover:bg-zinc-700'
                            }`}
                        title={isAudioLoading ? 'Loading...' : isPlayingSound ? 'Pause Music' : 'Play Music'}
                    >
                        <Music className={`w-6 h-6 ${isAudioLoading ? 'animate-pulse' : ''}`} />
                    </button>

                    {/* Reset Timer */}
                    <button
                        onClick={resetTimer}
                        className="p-4 rounded-full bg-zinc-800 text-zinc-400 hover:text-white hover:bg-zinc-700 transition-all"
                        title="Reset Timer"
                    >
                        <RotateCcw className="w-6 h-6" />
                    </button>
                </div>
                {/* Credits */}
                <div className="pt-8 text-xs text-zinc-600 text-center">
                    <p>Music by Scott Buckley, Tokyo Music Walker & others</p>
                    <p className="mt-1">Provided by <a href="https://www.chosic.com/free-music/all/" target="_blank" rel="noreferrer" className="hover:text-zinc-500 underline">Chosic.com</a></p>
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Helmet } from 'react-helmet-async';
import api from '../lib/axios';
import { Plus, Check, Flame, Trash2, TrendingUp, Calendar, GripVertical, Pencil, History, Sparkles, X } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import confetti from 'canvas-confetti';
import {
    DndContext,
    closestCenter,
    KeyboardSensor,
    PointerSensor,
    useSensor,
    useSensors,
} from '@dnd-kit/core';
import {
    arrayMove,
    SortableContext,
    sortableKeyboardCoordinates,
    verticalListSortingStrategy,
    useSortable
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

// Helper for safe date comparison
const isSameDay = (d1, d2) => {
    const date1 = new Date(d1);
    const date2 = new Date(d2);
    return date1.getFullYear() === date2.getFullYear() &&
        date1.getMonth() === date2.getMonth() &&
        date1.getDate() === date2.getDate();
};

// Sortable Row Component
function SortableRow({ habit, tableDates, handleToggleDate, handleDelete, getMonthlyProgress, handleUpdateName }) {
    const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: habit._id });
    const [isEditing, setIsEditing] = useState(false);
    const [editName, setEditName] = useState(habit.name);

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
    };

    const saveEdit = () => {
        if (editName.trim() !== habit.name) {
            handleUpdateName(habit._id, editName);
        }
        setIsEditing(false);
    };

    return (
        <tr ref={setNodeRef} style={style} className="border-b border-zinc-800 hover:bg-zinc-800/30 transition-colors group">
            <td className="p-4 w-10 hidden md:table-cell">
                <div {...attributes} {...listeners} className="cursor-grab active:cursor-grabbing">
                    <GripVertical className="w-4 h-4 text-zinc-600 hover:text-zinc-400" />
                </div>
            </td>
            <td className="p-4 pl-2 w-1/3 min-w-[140px] sticky left-0 z-10 bg-zinc-900 md:bg-transparent border-r border-zinc-800 md:border-none shadow-[2px_0_5px_rgba(0,0,0,0.3)] md:shadow-none">
                {isEditing ? (
                    <input
                        type="text"
                        value={editName}
                        onChange={(e) => setEditName(e.target.value)}
                        onBlur={saveEdit}
                        onKeyDown={(e) => e.key === 'Enter' && saveEdit()}
                        className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white w-full focus:outline-none focus:border-indigo-500"
                        autoFocus
                    />
                ) : (
                    <div onClick={() => setIsEditing(true)} className="cursor-pointer">
                        <div className="font-medium text-white truncate max-w-[120px] md:max-w-none">{habit.name}</div>
                        <Pencil className="w-3 h-3 inline-block ml-2 opacity-0 group-hover:opacity-50" />
                    </div>
                )}
                <div className="text-xs text-zinc-500">Best: {habit.bestStreak}</div>
            </td>
            {tableDates.map((date, i) => {
                const isDone = habit.completedDates.some(d => isSameDay(d, date));
                return (
                    <td key={i} className="p-2 md:p-4 text-center">
                        <button
                            onClick={() => handleToggleDate(habit._id, new Date(date))}
                            className={`w-6 h-6 md:w-8 md:h-8 rounded-lg transition-all ${isDone ? 'bg-indigo-600 hover:bg-indigo-500' : 'bg-zinc-800 hover:bg-zinc-700'}`}
                        >
                            {isDone && <Check className="w-3 h-3 md:w-4 md:h-4 text-white mx-auto" />}
                        </button>
                    </td>
                );
            })}
            <td className="p-2 md:p-4 text-center">
                <div className="flex items-center gap-2 justify-center">
                    <Flame className="w-4 h-4 text-orange-500 shrink-0" />
                    <span className="font-bold text-orange-500">{habit.streak}</span>
                </div>
            </td>
            <td className="p-4 hidden md:table-cell">
                <div className="w-full bg-zinc-800 rounded-full h-2">
                    <div className="bg-gradient-to-r from-indigo-500 to-purple-500 h-2 rounded-full transition-all" style={{ width: `${getMonthlyProgress(habit)}%` }}></div>
                </div>
                <div className="text-xs text-zinc-500 mt-1">{getMonthlyProgress(habit)}%</div>
            </td>
            <td className="p-2 md:p-4 text-right">
                <button onClick={() => handleDelete(habit._id)} className="text-red-500 hover:text-red-400 transition-colors">
                    <Trash2 className="w-4 h-4" />
                </button>
            </td>
        </tr>
    );
}

// Main Component
export default function HabitsPage() {
    const queryClient = useQueryClient();
    const [newHabit, setNewHabit] = useState('');
    const [viewMode, setViewMode] = useState(() => window.innerWidth < 768 ? 'grid' : 'table');
    const [showCalendar, setShowCalendar] = useState(false);
    const [currentDate] = useState(new Date());
    const [isAnalyzing, setIsAnalyzing] = useState(false);
    const [analysisResult, setAnalysisResult] = useState(null);

    // Update viewMode on window resize
    useEffect(() => {
        const onResize = () => setViewMode(window.innerWidth < 768 ? 'grid' : 'table');
        window.addEventListener('resize', onResize);
        return () => window.removeEventListener('resize', onResize);
    }, []);

    const { data: habits = [], isLoading: loading } = useQuery({
        queryKey: ['habits'],
        queryFn: async () => {
            const res = await api.get('/habits');
            return Array.isArray(res.data) ? res.data.sort((a, b) => a.order - b.order) : [];
        }
    });

    const handleAnalyze = async () => {
        setIsAnalyzing(true);
        try {
            const res = await api.post('/chat/analyze-habits');
            setAnalysisResult(res.data.analysis);
        } catch (err) {
            console.error(err);
            alert("Failed to analyze habits.");
        } finally {
            setIsAnalyzing(false);
        }
    };


    const sensors = useSensors(
        useSensor(PointerSensor),
        useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
    );

    // Mutations
    const reorderMutation = useMutation({
        mutationFn: (newHabits) => api.put('/habits/reorder', newHabits.map((h, i) => ({ id: h._id, order: i }))),
        onMutate: async (newHabits) => {
            await queryClient.cancelQueries(['habits']);
            const previous = queryClient.getQueryData(['habits']);
            queryClient.setQueryData(['habits'], newHabits);
            return { previous };
        },
        onError: (err, newHabits, context) => queryClient.setQueryData(['habits'], context.previous),
        onSettled: () => queryClient.invalidateQueries(['habits'])
    });

    const addMutation = useMutation({
        mutationFn: (name) => api.post('/habits', { name }),
        onSuccess: () => {
            setNewHabit('');
            queryClient.invalidateQueries(['habits']);
        }
    });

    const toggleMutation = useMutation({
        mutationFn: async ({ id, date }) => {
            // Send standard YYYY-MM-DD string (Local Time)
            const offset = date.getTimezoneOffset();
            const localDate = new Date(date.getTime() - (offset * 60 * 1000));
            const dateStr = localDate.toISOString().split('T')[0];
            return api.put(`/habits/${id}/toggle`, { date: dateStr });
        },
        onMutate: async ({ id, date }) => {
            await queryClient.cancelQueries(['habits']);
            const previousHabits = queryClient.getQueryData(['habits']);

            queryClient.setQueryData(['habits'], old => old.map(h => {
                if (h._id === id) {
                    const isDone = h.completedDates.some(d => isSameDay(d, date));
                    // Check logic for confetti (optimistic)
                    if (!isDone && isSameDay(date, new Date())) {
                        confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 } });
                    }

                    // Toggle date locally for instant UI
                    let newDates = [...h.completedDates];
                    if (isDone) {
                        newDates = newDates.filter(d => !isSameDay(d, date));
                    } else {
                        newDates.push(date.toISOString());
                    }

                    // Simple streak update (approximate)
                    let newStreak = h.streak;
                    if (!isDone && isSameDay(date, new Date())) newStreak += 1; // Increment if doing today

                    return { ...h, completedDates: newDates, streak: newStreak };
                }
                return h;
            }));

            return { previousHabits };
        },
        onError: (err, vars, context) => queryClient.setQueryData(['habits'], context.previousHabits),
        onSettled: () => queryClient.invalidateQueries(['habits'])
    });

    const deleteMutation = useMutation({
        mutationFn: (id) => api.delete(`/habits/${id}`),
        onMutate: async (id) => {
            await queryClient.cancelQueries(['habits']);
            const previous = queryClient.getQueryData(['habits']);
            queryClient.setQueryData(['habits'], old => old.filter(h => h._id !== id));
            return { previous };
        },
        onError: (err, id, context) => queryClient.setQueryData(['habits'], context.previous),
        onSettled: () => queryClient.invalidateQueries(['habits'])
    });

    const updateNameMutation = useMutation({
        mutationFn: ({ id, name }) => api.put(`/habits/${id}`, { name }),
        onSettled: () => queryClient.invalidateQueries(['habits'])
    });

    // Handlers
    const handleDragEnd = (event) => {
        const { active, over } = event;
        if (!over || active.id === over.id) return;
        const oldIndex = habits.findIndex(h => h._id === active.id);
        const newIndex = habits.findIndex(h => h._id === over.id);
        const newHabits = arrayMove(habits, oldIndex, newIndex);
        reorderMutation.mutate(newHabits);
    };

    const handleAdd = (e) => {
        e.preventDefault();
        if (!newHabit.trim()) return;
        addMutation.mutate(newHabit);
    };

    const handleToggleDate = (id, date) => {
        toggleMutation.mutate({ id, date });
    };

    const handleDelete = (id) => {
        if (!confirm('Delete this habit?')) return;
        deleteMutation.mutate(id);
    };

    const handleUpdateName = (id, newName) => {
        updateNameMutation.mutate({ id, name: newName });
    };

    const getLast7Days = () => {
        const days = [];
        for (let i = 6; i >= 0; i--) {
            const d = new Date();
            d.setDate(d.getDate() - i);
            days.push(d);
        }
        return days;
    };

    const getLast30Days = () => {
        const days = [];
        // Calculate based on last 30 days
        for (let i = 29; i >= 0; i--) {
            const d = new Date();
            d.setDate(d.getDate() - i);
            days.push(d);
        }
        return days;
    };

    const getMonthlyProgress = (habit) => {
        const last30 = getLast30Days();
        // Check completion count in the last 30 days
        const completed = last30.filter(d => habit.completedDates.some(cd => isSameDay(cd, d))).length;
        // Return percentage
        return Math.round((completed / 30) * 100);
    };

    const getWeeklyProgress = (habit) => {
        const last7 = getLast7Days();
        const completed = last7.filter(d => habit.completedDates.some(cd => isSameDay(cd, d))).length;
        return Math.round((completed / 7) * 100);
    };

    const getHeatmapData = () => {
        const data = [];
        for (let i = 59; i >= 0; i--) {
            const d = new Date();
            d.setDate(d.getDate() - i);
            const completedCount = habits.filter(h => h.completedDates.some(cd => isSameDay(cd, d))).length;
            const intensity = habits.length > 0 ? completedCount / habits.length : 0;
            data.push({ date: d, intensity });
        }
        return data;
    };

    const getDailyProgress = (date) => {
        if (!habits.length) return 0;
        const validHabits = habits.length;
        const completedCount = habits.filter(h =>
            h.completedDates.some(d => isSameDay(d, date))
        ).length;
        return Math.round((completedCount / validHabits) * 100);
    };

    const getDailyStatus = (percentage) => {
        if (percentage === 100) return { text: "Perfect!", color: "text-green-400" };
        if (percentage >= 80) return { text: "Well done", color: "text-indigo-400" };
        if (percentage >= 50) return { text: "Good job", color: "text-blue-400" };
        return { text: "Keep going", color: "text-zinc-500" };
    };

    const heatmapData = getHeatmapData();
    const tableDates = getLast7Days();

    return (
        <div className="p-4 md:p-8 max-w-7xl mx-auto space-y-10 relative">
            <Helmet>
                <title>Habit Tracker | Life OS</title>
            </Helmet>
            {/* Header */}
            <div className="flex flex-col md:flex-row items-start md:items-end justify-between gap-4 md:gap-4">
                <div className="w-full md:w-auto">
                    <h1 className="text-3xl md:text-4xl font-bold bg-gradient-to-r from-indigo-400 to-purple-400 bg-clip-text text-transparent">Habit Tracker</h1>
                    <div className="flex items-center gap-2 text-sm text-zinc-500 mt-2">
                        <span className="uppercase tracking-wider font-medium">{currentDate.toLocaleDateString('en-US', { weekday: 'long' })}</span>
                        <span className="w-1 h-1 bg-zinc-600 rounded-full"></span>
                        <span>
                            {currentDate.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}
                        </span>
                    </div>
                </div>

                <div className="grid grid-cols-2 sm:flex flex-wrap items-center gap-2 w-full md:w-auto mt-2 md:mt-0">
                    <button
                        onClick={handleAnalyze}
                        disabled={isAnalyzing}
